@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    @apply font-sans text-body text-text-primary bg-background antialiased;
    font-variant-numeric: tabular-nums;
    line-height: 1.5;
  }

  h1, h2, h3, h4 {
    line-height: 1.25;
  }

  * {
    transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
  }

  @media (prefers-reduced-motion: reduce) {
    * {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }
}

@layer components {
  .btn {
    @apply px-4 rounded font-medium transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2;
    min-height: 36px;
  }

  .btn-primary {
    @apply btn bg-primary text-white hover:bg-primary-hover;
  }

  .btn-secondary {
    @apply btn bg-surface text-text-primary border border-border hover:bg-gray-50;
  }

  .btn-ghost {
    @apply btn bg-transparent text-text-primary hover:bg-gray-100;
  }

  .btn-destructive {
    @apply btn bg-danger text-white hover:bg-red-700;
  }

  .input {
    @apply w-full px-3 py-2 border border-border rounded bg-surface text-text-primary placeholder:text-text-muted focus:outline-none focus:ring-2 focus:ring-primary;
  }

  .label {
    @apply block text-sm font-medium text-text-primary mb-1;
  }

  .card {
    @apply bg-surface rounded-card shadow-sm border border-border;
  }

  .modal-backdrop {
    @apply fixed inset-0 bg-black/50 backdrop-blur-sm;
  }

  .modal {
    @apply fixed inset-0 flex items-center justify-center p-4 z-50;
  }

  .modal-content {
    @apply bg-surface rounded-card shadow-2xl max-w-md w-full p-6;
  }
}

