import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';
import { format } from 'date-fns';

const HABIT_COLORS: Record<string, string> = {
  indigo: '#4F46E5',
  teal: '#0D9488',
  amber: '#D97706',
  rose: '#E11D48',
  slate: '#475569',
  forest: '#166534',
};

export function Dashboard() {
  const queryClient = useQueryClient();
  const { data: dashboard, isLoading } = useQuery({
    queryKey: ['dashboard'],
    queryFn: () => api.getDashboard(),
  });

  const toggleComplete = useMutation({
    mutationFn: async ({ habitId, completed }: { habitId: string; completed: boolean }) => {
      const today = format(new Date(), 'yyyy-MM-dd');
      if (completed) {
        await api.uncompleteHabit(habitId, { date: today });
      } else {
        await api.completeHabit(habitId, { date: today });
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    },
  });

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-48 mb-8"></div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            {[1, 2, 3].map((i) => (
              <div key={i} className="card p-6 h-24"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (!dashboard || dashboard.habits.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <h1 className="text-heading-1 font-semibold mb-8">Dashboard</h1>
        <div className="card p-12 text-center">
          <p className="text-text-muted mb-4">No habits yet</p>
          <a href="/habits" className="btn-primary inline-block">
            Add your first habit
          </a>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <h1 className="text-heading-1 font-semibold mb-8">Dashboard</h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="card p-6">
          <div className="text-caption text-text-muted uppercase tracking-wide mb-2">
            Total Habits
          </div>
          <div className="text-heading-1 font-mono font-semibold text-text-primary">
            {dashboard.total_habits}
          </div>
        </div>

        <div className="card p-6">
          <div className="text-caption text-text-muted uppercase tracking-wide mb-2">
            Active Streaks
          </div>
          <div className="text-heading-1 font-mono font-semibold text-text-primary">
            {dashboard.habits_with_active_streak}
          </div>
        </div>

        <div className="card p-6">
          <div className="text-caption text-text-muted uppercase tracking-wide mb-2">
            Total Completions
          </div>
          <div className="text-heading-1 font-mono font-semibold text-text-primary">
            {dashboard.total_completions}
          </div>
        </div>
      </div>

      <div className="card">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="border-b border-border bg-gray-50">
              <tr>
                <th className="text-left px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                  Habit
                </th>
                <th className="text-center px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                  Current Streak
                </th>
                <th className="text-center px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                  Longest Streak
                </th>
                <th className="text-center px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                  Today
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {dashboard.habits.map((habit) => (
                <tr key={habit.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div
                        className="w-3 h-3 rounded-full"
                        style={{ backgroundColor: HABIT_COLORS[habit.color] }}
                      />
                      <span className="font-medium text-text-primary">{habit.name}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="font-mono text-body-lg font-semibold text-text-primary">
                      {habit.current_streak}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className="font-mono text-body-lg font-semibold text-text-muted">
                      {habit.longest_streak}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <button
                      onClick={() =>
                        toggleComplete.mutate({
                          habitId: habit.id,
                          completed: habit.completed_today,
                        })
                      }
                      disabled={toggleComplete.isPending}
