import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '../lib/api';
import type { HabitColor } from '../types';

const HABIT_COLORS: Record<HabitColor, string> = {
  indigo: '#4F46E5',
  teal: '#0D9488',
  amber: '#D97706',
  rose: '#E11D48',
  slate: '#475569',
  forest: '#166534',
};

const COLOR_OPTIONS: HabitColor[] = ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest'];

export function Habits() {
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    color: 'indigo' as HabitColor,
    description: '',
  });
  const [error, setError] = useState('');

  const queryClient = useQueryClient();
  const { data: habits, isLoading } = useQuery({
    queryKey: ['habits'],
    queryFn: () => api.getHabits(),
  });

  const createMutation = useMutation({
    mutationFn: api.createHabit,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      setShowModal(false);
      resetForm();
    },
    onError: (err) => {
      setError(err instanceof Error ? err.message : 'Failed to create habit');
    },
  });

  const updateMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: any }) => api.updateHabit(id, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      setShowModal(false);
      resetForm();
    },
    onError: (err) => {
      setError(err instanceof Error ? err.message : 'Failed to update habit');
    },
  });

  const deleteMutation = useMutation({
    mutationFn: api.deleteHabit,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habits'] });
      setDeleteId(null);
    },
  });

  const resetForm = () => {
    setFormData({ name: '', color: 'indigo', description: '' });
    setEditingId(null);
    setError('');
  };

  const openCreateModal = () => {
    resetForm();
    setShowModal(true);
  };

  const openEditModal = (habit: any) => {
    setFormData({
      name: habit.name,
      color: habit.color,
      description: habit.description || '',
    });
    setEditingId(habit.id);
    setShowModal(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const data = {
      name: formData.name.trim(),
      color: formData.color,
      description: formData.description.trim() || undefined,
    };

    if (editingId) {
      updateMutation.mutate({ id: editingId, data });
    } else {
      createMutation.mutate(data);
    }
  };

  const handleDelete = (id: string) => {
    deleteMutation.mutate(id);
  };

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-48 mb-8"></div>
          <div className="card p-6">
            <div className="space-y-4">
              {[1, 2, 3].map((i) => (
                <div key={i} className="h-12 bg-gray-200 rounded"></div>
              ))}
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-heading-1 font-semibold">Habits</h1>
        <button onClick={openCreateModal} className="btn-primary h-11">
          Add habit
        </button>
      </div>

      {!habits || habits.length === 0 ? (
        <div className="card p-12 text-center">
          <p className="text-text-muted mb-4">No habits yet</p>
          <button onClick={openCreateModal} className="btn-primary">
            Add your first habit
          </button>
        </div>
      ) : (
        <div className="card">
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="border-b border-border bg-gray-50 sticky top-0">
                <tr>
                  <th className="text-left px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                    Habit
                  </th>
                  <th className="text-center px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                    Current Streak
                  </th>
                  <th className="text-center px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                    Longest Streak
                  </th>
                  <th className="text-right px-6 py-3 text-caption font-semibold text-text-muted uppercase tracking-wide">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border">
                {habits.map((habit) => (
                  <tr key={habit.id} className="hover:bg-gray-50 transition-colors h-[36px]">
                    <td className="px-6 py-2">
                      <div className="flex items-center gap-3">
                        <div
                          className="w-3 h-3 rounded-full flex-shrink-0"
                          style={{ backgroundColor: HABIT_COLORS[habit.color] }}
                        />
                        <div>
                          <div className="font-medium text-text-primary">{habit.name}</div>
                          {habit.description && (
                            <div className="text-caption text-text-muted">{habit.description}</div>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-2 text-center">
                      <span className="font-mono text-body-lg font-semibold text-text-primary">
                        {habit.current_streak}
                      </span>
                    </td>
                    <td className="px-6 py-2 text-center">
                      <span className="font-mono text-body-lg font-semibold text-text-muted">
                        {habit.longest_streak}
                      </span>
                    </td>
                    <td className="px-6 py-2 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <a
                          href={`/habits/${habit.id}`}
                          className="btn-ghost px-3 h-7 text-sm"
                        >
                          View
                        </a>
                        <button
                          onClick={() => openEditModal(habit)}
                          className="btn-ghost px-3 h-7 text-sm"
                        >
                          Edit
                        </button>
                        <button
                          onClick={() => setDeleteId(habit.id)}
                          className="btn-ghost px-3 h-7 text-sm text-danger hover:bg-red-50"
                        >
                          Delete
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Create/Edit Modal */}
      {showModal && (
        <div className="modal" onClick={() => setShowModal(false)}>
          <div className="modal-backdrop" />
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-heading-2 font-semibold mb-6">
              {editingId ? 'Edit habit' : 'Add habit'}
            </h2>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label htmlFor="name" className="label">
                  Name
                </label>
                <input
                  id="name"
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="input"
                  placeholder="Meditate"
                  maxLength={80}
                  required
                  autoFocus
                />
              </div>

              <div>
                <label htmlFor="description" className="label">
                  Description (optional)
                </label>
                <input
                  id="description"
                  type="text"
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  className="input"
                  placeholder="10 minutes each morning"
                  maxLength={200}
                />
              </div>

              <div>
                <label className="label">Color</label>
                <div className="flex gap-3">
                  {COLOR_OPTIONS.map((color) => (
                    <button
                      key={color}
                      type="button"
                      onClick={() => setFormData({ ...formData, color })}
                      className={`w-10 h-10 rounded-full border-2 transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 ${
                        formData.color === color ? 'border-gray-900 scale-110' : 'border-transparent'
                      }`}
                      style={{ backgroundColor: HABIT_COLORS[color] }}
                      aria-label={color}
                    />
                  ))}
                </div>
              </div>

              {error && (
                <div className="text-sm text-danger bg-red-50 border border-red-200 rounded p-3">
                  {error}
                </div>
              )}

              <div className="flex gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="btn-secondary flex-1 h-11"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={createMutation.isPending || updateMutation.isPending}
                  className="btn-primary flex-1 h-11 disabled:opacity-50"
                >
                  {editingId ? 'Update' : 'Create'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteId && (
        <div className="modal" onClick={() => setDeleteId(null)}>
          <div className="modal-backdrop" />
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-heading-2 font-semibold mb-4">Delete habit?</h2>
            <p className="text-text-muted mb-6">
              This will hide the habit from your list. Your completion history will be preserved.
            </p>
            <div className="flex gap-3">
              <button
                onClick={() => setDeleteId(null)}
                className="btn-secondary flex-1 h-11"
              >
                Cancel
              </button>
              <button
                onClick={() => handleDelete(deleteId)}
                disabled={deleteMutation.isPending}
                className="btn-destructive flex-1 h-11 disabled:opacity-50"
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

