import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { format, subDays, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, parseISO } from 'date-fns';
import { api } from '../lib/api';

const HABIT_COLORS: Record<string, string> = {
  indigo: '#4F46E5',
  teal: '#0D9488',
  amber: '#D97706',
  rose: '#E11D48',
  slate: '#475569',
  forest: '#166534',
};

export function HabitDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [currentMonth] = useState(new Date());

  const { data: habit, isLoading } = useQuery({
    queryKey: ['habit', id],
    queryFn: () => api.getHabit(id!),
    enabled: !!id,
  });

  const toggleComplete = useMutation({
    mutationFn: async ({ date, completed }: { date: string; completed: boolean }) => {
      if (completed) {
        await api.uncompleteHabit(id!, { date });
      } else {
        await api.completeHabit(id!, { date });
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['habit', id] });
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
    },
  });

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-48 mb-8"></div>
          <div className="card p-6 h-96"></div>
        </div>
      </div>
    );
  }

  if (!habit) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="card p-12 text-center">
          <p className="text-text-muted mb-4">Habit not found</p>
          <button onClick={() => navigate('/habits')} className="btn-primary">
            Back to habits
          </button>
        </div>
      </div>
    );
  }

  // Generate calendar days for the last 12 weeks
  const today = new Date();
  const startDate = subDays(today, 84); // 12 weeks
  const days = eachDayOfInterval({ start: startDate, end: today });

  // Mock completion data - in real app, fetch from API
  const completions = new Set<string>();
  // This would normally come from the API
  // For now, we'll just mark today if completed_today is true
  if (habit.completed_today) {
    completions.add(format(today, 'yyyy-MM-dd'));
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <button
        onClick={() => navigate('/habits')}
        className="btn-ghost mb-6 -ml-4"
      >
        ← Back to habits
      </button>

      <div className="mb-8">
        <div className="flex items-center gap-3 mb-2">
          <div
            className="w-4 h-4 rounded-full"
            style={{ backgroundColor: HABIT_COLORS[habit.color] }}
          />
          <h1 className="text-heading-1 font-semibold">{habit.name}</h1>
        </div>
        {habit.description && (
          <p className="text-text-muted ml-7">{habit.description}</p>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="card p-6">
          <div className="text-caption text-text-muted uppercase tracking-wide mb-2">
            Current Streak
          </div>
          <div className="text-heading-1 font-mono font-semibold text-text-primary">
            {habit.current_streak}
          </div>
        </div>

        <div className="card p-6">
          <div className="text-caption text-text-muted uppercase tracking-wide mb-2">
            Longest Streak
          </div>
          <div className="text-heading-1 font-mono font-semibold text-text-primary">
            {habit.longest_streak}
          </div>
        </div>

        <div className="card p-6">
          <div className="text-caption text-text-muted uppercase tracking-wide mb-2">
            Completed Today
          </div>
          <div className="text-heading-1 font-mono font-semibold text-text-primary">
            {habit.completed_today ? 'Yes' : 'No'}
          </div>
        </div>
      </div>

      <div className="card p-6">
        <h2 className="text-heading-3 font-semibold mb-6">Completion Calendar</h2>

        <div className="grid grid-cols-7 gap-2">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day) => (
            <div key={day} className="text-center text-caption text-text-muted font-medium">
              {day}
            </div>
          ))}

          {days.map((day) => {
            const dateStr = format(day, 'yyyy-MM-dd');
            const isCompleted = completions.has(dateStr);
            const isToday = isSameDay(day, today);
            const isFuture = day > today;

            return (
              <button
                key={dateStr}
                onClick={() => {
                  if (!isFuture) {
                    toggleComplete.mutate({ date: dateStr, completed: isCompleted });
                  }
                }}
                disabled={isFuture || toggleComplete.isPending}
                className={`
                  aspect-square rounded text-caption font-medium transition-all
                  focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2
                  disabled:cursor-not-allowed disabled:opacity-30
                  ${isToday ? 'ring-2 ring-offset-1' : ''}
                `}
                style={{
                  backgroundColor: isCompleted ? HABIT_COLORS[habit.color] : '#F3F4F6',
                  color: isCompleted ? '#FFFFFF' : '#6B7280',
                  ringColor: isToday ? HABIT_COLORS[habit.color] : undefined,
                }}
                title={dateStr}
              >
                {format(day, 'd')}
              </button>
            );
          })}
        </div>

        <div className="mt-6 flex items-center gap-6 text-sm text-text-muted">
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded bg-gray-100"></div>
            <span>Not completed</span>
          </div>
          <div className="flex items-center gap-2">
            <div
              className="w-4 h-4 rounded"
              style={{ backgroundColor: HABIT_COLORS[habit.color] }}
            ></div>
            <span>Completed</span>
          </div>
        </div>
      </div>
    </div>
  );
}

