              <button
                onClick={handleLogout}
                className="text-body text-text-muted hover:text-text-primary transition-colors"
              >
                Sign out
              </button>
            </div>
          </div>

          {/* Mobile menu */}
          <div className="md:hidden pb-4 flex gap-6">
            <Link
              to="/"
              className="text-body text-text-muted hover:text-text-primary transition-colors"
            >
              Dashboard
            </Link>
            <Link
              to="/habits"
              className="text-body text-text-muted hover:text-text-primary transition-colors"
            >
              Habits
            </Link>
          </div>
        </div>
      </nav>

      <main className="flex-1">{children}</main>
    </div>
  );
}

