const PocketBase = require('pocketbase');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const pb = new PocketBase(BACKEND_URL);

// Password for all seeded accounts
const SEED_PASSWORD = 'deku-demo-pw-2026';

async function initPocketBase() {
  try {
    console.log('Initializing PocketBase...');
    console.log('Backend URL:', BACKEND_URL);

    // Authenticate as admin (PocketBase default admin)
    // For a fresh PocketBase instance, we may need to create an admin first
    // or use the default credentials if they exist

    // Try to authenticate with default admin credentials
    // If this fails, we'll need to create collections differently
    let isAdmin = false;
    try {
      await pb.admins.authWithPassword('admin@example.com', 'admin1234');
      isAdmin = true;
      console.log('Authenticated as admin');
    } catch (err) {
      console.log('No admin auth available, will try direct collection creation');
    }

    // Check if habits collection exists
    let habitsCollection, completionsCollection;

    try {
      habitsCollection = await pb.collections.getOne('habits');
      console.log('Habits collection already exists');
    } catch (err) {
      console.log('Creating habits collection...');
      habitsCollection = await pb.collections.create({
        name: 'habits',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'name',
            type: 'text',
            required: true,
            options: {
              min: 1,
              max: 80,
              pattern: ''
            }
          },
          {
            name: 'description',
            type: 'text',
            required: false,
            options: {
              min: null,
              max: 200,
              pattern: ''
            }
          },
          {
            name: 'color',
            type: 'select',
            required: true,
            options: {
              maxSelect: 1,
              values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest']
            }
          },
          {
            name: 'deleted',
            type: 'bool',
            required: true,
            options: {}
          }
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_user_name ON habits (user_id, LOWER(name)) WHERE deleted = FALSE'
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = false',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      });
      console.log('Habits collection created');
    }

    try {
      completionsCollection = await pb.collections.getOne('completions');
      console.log('Completions collection already exists');
    } catch (err) {
      console.log('Creating completions collection...');
      completionsCollection = await pb.collections.create({
        name: 'completions',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'habit_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: habitsCollection.id,
              cascadeDelete: true,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'date',
            type: 'text',
            required: true,
            options: {
              min: 10,
              max: 10,
              pattern: '^\\d{4}-\\d{2}-\\d{2}$'
            }
          }
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_unique_completion ON completions (user_id, habit_id, date)'
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: null,
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      });
      console.log('Completions collection created');
    }

    // Create seed user
    let seedUser;
    try {
      // Try to find existing user
      const users = await pb.collection('users').getFullList({
        filter: 'email = "demo@ethara.ai"'
      });
      if (users.length > 0) {
        seedUser = users[0];
        console.log('Seed user already exists');
      } else {
        throw new Error('User not found');
      }
    } catch (err) {
      console.log('Creating seed user...');
      seedUser = await pb.collection('users').create({
        email: 'demo@ethara.ai',
        password: SEED_PASSWORD,
        passwordConfirm: SEED_PASSWORD,
        verified: true
      });
      console.log('Seed user created');
    }

    // Authenticate as the seed user to create their data
    await pb.collection('users').authWithPassword('demo@ethara.ai', SEED_PASSWORD);
    console.log('Authenticated as seed user');

    // Check if habits already exist
    const existingHabits = await pb.collection('habits').getFullList({
      filter: `user_id = "${seedUser.id}"`
    });

    if (existingHabits.length > 0) {
      console.log('Seed habits already exist');
      return;
    }

    // Create seed habits
    console.log('Creating seed habits...');
    const meditateHabit = await pb.collection('habits').create({
      user_id: seedUser.id,
      name: 'Meditate',
      color: 'indigo',
      deleted: false
    });

    const readHabit = await pb.collection('habits').create({
      user_id: seedUser.id,
      name: 'Read 20 minutes',
      color: 'teal',
      deleted: false
    });

    const sodaHabit = await pb.collection('habits').create({
      user_id: seedUser.id,
      name: 'No soda',
      color: 'amber',
      deleted: false
    });

    console.log('Seed habits created');

    // Create completions
    console.log('Creating seed completions...');
    const today = new Date();
    const formatDate = (date) => {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    };

    // Meditate: current streak of 5 (today and 4 days before)
    for (let i = 0; i < 5; i++) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      await pb.collection('completions').create({
        user_id: seedUser.id,
        habit_id: meditateHabit.id,
        date: formatDate(date)
      });
    }

    // Read 20 minutes: longest streak of 3, but not today
    for (let i = 7; i < 10; i++) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      await pb.collection('completions').create({
        user_id: seedUser.id,
        habit_id: readHabit.id,
        date: formatDate(date)
      });
    }

    // No soda: current streak of 1 (only today)
    await pb.collection('completions').create({
      user_id: seedUser.id,
      habit_id: sodaHabit.id,
      date: formatDate(today)
    });

    console.log('Seed completions created');
    console.log('PocketBase initialization complete!');

  } catch (error) {
    console.error('Error initializing PocketBase:', error);
    throw error;
  }
}

// Run initialization
initPocketBase()
  .then(() => {
    console.log('Done!');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Failed:', error);
    process.exit(1);
  });

