      await pb.collection('completions').create({
        user_id: seedUser.id,
        habit_id: readHabit.id,
        date: formatDate(date)
      });
    }

    // No soda: current streak of 1 (only today)
    await pb.collection('completions').create({
      user_id: seedUser.id,
      habit_id: sodaHabit.id,
      date: formatDate(today)
    });

    console.log('Seed completions created');
    console.log('PocketBase initialization complete!');

  } catch (error) {
    console.error('Error initializing PocketBase:', error);
    throw error;
  }
}

// Run initialization
initPocketBase()
