const express = require('express');
const cors = require('cors');
const PocketBase = require('pocketbase').default;

const app = express();
const PORT = process.env.APP_PUBLIC_PORT || 4173;
const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';

// Middleware
app.use(cors());
app.use(express.json());
app.use(express.static('../frontend/dist'));

// PocketBase client
const pb = new PocketBase(BACKEND_URL);

// Helper function to calculate streaks
function calculateStreaks(completions, today) {
  if (!completions || completions.length === 0) {
    return { current_streak: 0, longest_streak: 0 };
  }

  // Sort completions by date (most recent first)
  const sorted = [...completions]
    .map(c => new Date(c.date))
    .sort((a, b) => b - a);

  const todayDate = new Date(today);
  todayDate.setHours(0, 0, 0, 0);

  // Calculate current streak
  let current_streak = 0;
  let checkDate = new Date(todayDate);

  for (let completion of sorted) {
    const completionDate = new Date(completion);
    completionDate.setHours(0, 0, 0, 0);

    const daysDiff = Math.floor((checkDate - completionDate) / (1000 * 60 * 60 * 24));

    if (daysDiff === 0) {
      current_streak++;
      checkDate.setDate(checkDate.getDate() - 1);
    } else if (daysDiff > 1) {
      break;
    } else {
      checkDate.setDate(checkDate.getDate() - 1);
    }
  }

  // Calculate longest streak
  let longest_streak = 0;
  let temp_streak = 1;

  for (let i = 0; i < sorted.length - 1; i++) {
    const current = new Date(sorted[i]);
    const next = new Date(sorted[i + 1]);
    current.setHours(0, 0, 0, 0);
    next.setHours(0, 0, 0, 0);

    const daysDiff = Math.floor((current - next) / (1000 * 60 * 60 * 24));

    if (daysDiff === 1) {
      temp_streak++;
      longest_streak = Math.max(longest_streak, temp_streak);
    } else {
      longest_streak = Math.max(longest_streak, temp_streak);
      temp_streak = 1;
    }
  }

  longest_streak = Math.max(longest_streak, temp_streak, current_streak);

  return { current_streak, longest_streak };
}

// Auth middleware
async function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    pb.authStore.save(token);
    if (!pb.authStore.isValid) {
      throw new Error('Invalid token');
    }
    req.user = pb.authStore.model;
    next();
  } catch (error) {
    return res.status(401).json({ message: 'Unauthorized' });
  }
}

// Routes

// Health check
app.get('/api/health', (req, res) => {
  res.json({ status: 'ok' });
});

// Auth login
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const authData = await pb.collection('users').authWithPassword(email, password);
    res.json({
      access_token: authData.token,
      token: authData.token,
      record: authData.record
    });
  } catch (error) {
    console.error('Login error:', error);
    res.status(401).json({ message: 'Invalid credentials' });
  }
});

// Get all habits
app.get('/api/habits', authMiddleware, async (req, res) => {
  try {
    const habits = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.user.id}" && deleted = false`,
      sort: 'created'
    });

    const today = new Date().toISOString().split('T')[0];

    const habitsWithStreaks = await Promise.all(habits.map(async (habit) => {
      const completions = await pb.collection('completions').getFullList({
        filter: `user_id = "${req.user.id}" && habit_id = "${habit.id}"`,
        sort: '-date'
      });

      const streaks = calculateStreaks(completions, today);
      const completed_today = completions.some(c => c.date === today);

      return {
        ...habit,
        ...streaks,
        completed_today
      };
    }));

    res.json(habitsWithStreaks);
  } catch (error) {
    console.error('Get habits error:', error);
    res.status(500).json({ message: 'Failed to fetch habits' });
  }
});

// Get single habit
app.get('/api/habits/:id', authMiddleware, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    if (habit.deleted) {
      return res.status(404).json({ message: 'Habit not found' });
    }

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${habit.id}"`,
      sort: '-date'
    });

    const today = new Date().toISOString().split('T')[0];
    const streaks = calculateStreaks(completions, today);
    const completed_today = completions.some(c => c.date === today);

    res.json({
      ...habit,
      ...streaks,
      completed_today
    });
  } catch (error) {
    console.error('Get habit error:', error);
    res.status(404).json({ message: 'Habit not found' });
  }
});

// Create habit
app.post('/api/habits', authMiddleware, async (req, res) => {
  try {
    const { name, color, description } = req.body;

    if (!name || !color) {
      return res.status(400).json({ message: 'Name and color are required' });
    }

    // Check for duplicate name (case-insensitive)
    const existing = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.user.id}" && LOWER(name) = LOWER("${name.replace(/"/g, '\\"')}") && deleted = false`
    });

    if (existing.length > 0) {
      return res.status(400).json({ message: 'A habit with this name already exists' });
    }

    const habit = await pb.collection('habits').create({
      user_id: req.user.id,
      name: name.trim(),
      color,
      description: description?.trim() || '',
      deleted: false
    });

    res.status(201).json({
      ...habit,
      current_streak: 0,
      longest_streak: 0,
      completed_today: false
    });
  } catch (error) {
    console.error('Create habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to create habit' });
  }
});

// Update habit
app.patch('/api/habits/:id', authMiddleware, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    const { name, color, description } = req.body;

    // If updating name, check for duplicates
    if (name && name.toLowerCase() !== habit.name.toLowerCase()) {
      const existing = await pb.collection('habits').getFullList({
        filter: `user_id = "${req.user.id}" && LOWER(name) = LOWER("${name.replace(/"/g, '\\"')}") && deleted = false && id != "${habit.id}"`
      });

      if (existing.length > 0) {
        return res.status(400).json({ message: 'A habit with this name already exists' });
      }
    }

    const updated = await pb.collection('habits').update(req.params.id, {
      name: name?.trim() || habit.name,
      color: color || habit.color,
      description: description !== undefined ? description.trim() : habit.description
    });

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${updated.id}"`,
      sort: '-date'
    });

    const today = new Date().toISOString().split('T')[0];
    const streaks = calculateStreaks(completions, today);
    const completed_today = completions.some(c => c.date === today);

    res.json({
      ...updated,
      ...streaks,
      completed_today
    });
  } catch (error) {
    console.error('Update habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to update habit' });
  }
});

// Delete habit (soft delete)
app.delete('/api/habits/:id', authMiddleware, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    await pb.collection('habits').update(req.params.id, { deleted: true });
    res.status(204).send();
  } catch (error) {
    console.error('Delete habit error:', error);
    res.status(404).json({ message: 'Habit not found' });
  }
});

// Complete habit
app.post('/api/habits/:id/complete', authMiddleware, async (req, res) => {
  try {
    const { date } = req.body;

    if (!date) {
      return res.status(400).json({ message: 'Date is required' });
    }

    // Check if date is in the future
    const today = new Date().toISOString().split('T')[0];
    if (date > today) {
      return res.status(400).json({ message: 'Cannot complete habit in the future' });
    }

    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    // Check if already completed
    const existing = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${req.params.id}" && date = "${date}"`
    });

    if (existing.length > 0) {
      return res.status(200).json({ message: 'Already completed' });
    }

    await pb.collection('completions').create({
      user_id: req.user.id,
      habit_id: req.params.id,
      date
    });

    res.status(201).json({ message: 'Habit completed' });
  } catch (error) {
    console.error('Complete habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to complete habit' });
  }
});

// Uncomplete habit
app.delete('/api/habits/:id/complete', authMiddleware, async (req, res) => {
  try {
    const { date } = req.body;

    if (!date) {
      return res.status(400).json({ message: 'Date is required' });
    }

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${req.params.id}" && date = "${date}"`
    });

    if (completions.length === 0) {
      return res.status(204).send();
    }

    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    await pb.collection('completions').delete(completions[0].id);
    res.status(204).send();
  } catch (error) {
    console.error('Uncomplete habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to uncomplete habit' });
  }
});

// Get dashboard
app.get('/api/dashboard', authMiddleware, async (req, res) => {
  try {
    const habits = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.user.id}" && deleted = false`,
      sort: 'created'
    });

    const allCompletions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}"`
    });

    const today = new Date().toISOString().split('T')[0];

    const habitsWithStreaks = await Promise.all(habits.map(async (habit) => {
      const completions = allCompletions.filter(c => c.habit_id === habit.id);
      const streaks = calculateStreaks(completions, today);
      const completed_today = completions.some(c => c.date === today);

      return {
        ...habit,
        ...streaks,
        completed_today
      };
    }));

    const habits_with_active_streak = habitsWithStreaks.filter(h => h.current_streak > 0).length;

    res.json({
      total_habits: habits.length,
      total_completions: allCompletions.length,
      habits_with_active_streak,
      habits: habitsWithStreaks
    });
  } catch (error) {
    console.error('Get dashboard error:', error);
    res.status(500).json({ message: 'Failed to fetch dashboard' });
  }
});

// Serve frontend for all other routes
app.get('*', (req, res) => {
  res.sendFile('/app/frontend/dist/index.html');
});

// Start server
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`PocketBase URL: ${BACKEND_URL}`);
});

