      current_streak: 0,
      longest_streak: 0,
      completed_today: false
    });
  } catch (error) {
    console.error('Create habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to create habit' });
  }
});

// Update habit
app.patch('/api/habits/:id', authMiddleware, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    const { name, color, description } = req.body;

    // If updating name, check for duplicates
    if (name && name.toLowerCase() !== habit.name.toLowerCase()) {
      const existing = await pb.collection('habits').getFullList({
        filter: `user_id = "${req.user.id}" && LOWER(name) = LOWER("${name.replace(/"/g, '\\"')}") && deleted = false && id != "${habit.id}"`
      });

      if (existing.length > 0) {
        return res.status(400).json({ message: 'A habit with this name already exists' });
      }
    }

    const updated = await pb.collection('habits').update(req.params.id, {
      name: name?.trim() || habit.name,
      color: color || habit.color,
      description: description !== undefined ? description.trim() : habit.description
    });

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${updated.id}"`,
      sort: '-date'
    });

    const today = new Date().toISOString().split('T')[0];
    const streaks = calculateStreaks(completions, today);
    const completed_today = completions.some(c => c.date === today);

    res.json({
      ...updated,
      ...streaks,
      completed_today
    });
  } catch (error) {
    console.error('Update habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to update habit' });
  }
});

// Delete habit (soft delete)
app.delete('/api/habits/:id', authMiddleware, async (req, res) => {
  try {
    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    await pb.collection('habits').update(req.params.id, { deleted: true });
    res.status(204).send();
  } catch (error) {
    console.error('Delete habit error:', error);
    res.status(404).json({ message: 'Habit not found' });
  }
});

// Complete habit
app.post('/api/habits/:id/complete', authMiddleware, async (req, res) => {
  try {
    const { date } = req.body;

    if (!date) {
      return res.status(400).json({ message: 'Date is required' });
    }

    // Check if date is in the future
    const today = new Date().toISOString().split('T')[0];
    if (date > today) {
      return res.status(400).json({ message: 'Cannot complete habit in the future' });
    }

    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    // Check if already completed
    const existing = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${req.params.id}" && date = "${date}"`
    });

    if (existing.length > 0) {
      return res.status(200).json({ message: 'Already completed' });
    }

    await pb.collection('completions').create({
      user_id: req.user.id,
      habit_id: req.params.id,
      date
    });

    res.status(201).json({ message: 'Habit completed' });
  } catch (error) {
    console.error('Complete habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to complete habit' });
  }
});

// Uncomplete habit
app.delete('/api/habits/:id/complete', authMiddleware, async (req, res) => {
  try {
    const { date } = req.body;

    if (!date) {
      return res.status(400).json({ message: 'Date is required' });
    }

    const completions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}" && habit_id = "${req.params.id}" && date = "${date}"`
    });

    if (completions.length === 0) {
      return res.status(204).send();
    }

    const habit = await pb.collection('habits').getOne(req.params.id);

    if (habit.user_id !== req.user.id) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    await pb.collection('completions').delete(completions[0].id);
    res.status(204).send();
  } catch (error) {
    console.error('Uncomplete habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to uncomplete habit' });
  }
});

// Get dashboard
app.get('/api/dashboard', authMiddleware, async (req, res) => {
  try {
    const habits = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.user.id}" && deleted = false`,
      sort: 'created'
    });

    const allCompletions = await pb.collection('completions').getFullList({
      filter: `user_id = "${req.user.id}"`
    });

    const today = new Date().toISOString().split('T')[0];

    const habitsWithStreaks = await Promise.all(habits.map(async (habit) => {
      const completions = allCompletions.filter(c => c.habit_id === habit.id);
      const streaks = calculateStreaks(completions, today);
      const completed_today = completions.some(c => c.date === today);

      return {
        ...habit,
        ...streaks,
        completed_today
      };
    }));

    const habits_with_active_streak = habitsWithStreaks.filter(h => h.current_streak > 0).length;

    res.json({
      total_habits: habits.length,
      total_completions: allCompletions.length,
      habits_with_active_streak,
      habits: habitsWithStreaks
    });
  } catch (error) {
    console.error('Get dashboard error:', error);
    res.status(500).json({ message: 'Failed to fetch dashboard' });
  }
});

// Serve frontend for all other routes
app.get('*', (req, res) => {
  res.sendFile('/app/frontend/dist/index.html');
});

// Start server
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`PocketBase URL: ${BACKEND_URL}`);
});

