const PocketBase = require('pocketbase').default;

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const SEED_PASSWORD = 'deku-demo-pw-2026';
const pb = new PocketBase(BACKEND_URL);

async function setupSeedData() {
  try {
    console.log('Setting up seed data...');
    console.log('Backend URL:', BACKEND_URL);

    // Try to find existing user
    let seedUser;
    try {
      const authData = await pb.collection('users').authWithPassword('demo@ethara.ai', SEED_PASSWORD);
      seedUser = authData.record;
      console.log('Seed user already exists, authenticated');
    } catch (err) {
      console.log('Seed user not found or wrong password, creating new user...');
      // Create seed user
      seedUser = await pb.collection('users').create({
        email: 'demo@ethara.ai',
        password: SEED_PASSWORD,
        passwordConfirm: SEED_PASSWORD,
      });

      // Authenticate as the new user
      await pb.collection('users').authWithPassword('demo@ethara.ai', SEED_PASSWORD);
      console.log('Seed user created and authenticated');
    }

    // Check if habits already exist
    const existingHabits = await pb.collection('habits').getFullList({
      filter: `user_id = "${seedUser.id}"`
    }).catch(() => []);

    if (existingHabits.length > 0) {
      console.log('Seed habits already exist, skipping creation');
      return;
    }

    // Create seed habits
    console.log('Creating seed habits...');

    const meditateHabit = await pb.collection('habits').create({
      user_id: seedUser.id,
      name: 'Meditate',
      color: 'indigo',
      description: '',
      deleted: false
    });
    console.log('Created: Meditate');

    const readHabit = await pb.collection('habits').create({
      user_id: seedUser.id,
      name: 'Read 20 minutes',
      color: 'teal',
      description: '',
      deleted: false
    });
    console.log('Created: Read 20 minutes');

    const sodaHabit = await pb.collection('habits').create({
      user_id: seedUser.id,
      name: 'No soda',
      color: 'amber',
      description: '',
      deleted: false
    });
    console.log('Created: No soda');

    // Create completions
    console.log('Creating seed completions...');

    const today = new Date();
    const formatDate = (date) => {
      const year = date.getFullYear();
      const month = String(date.getMonth() + 1).padStart(2, '0');
      const day = String(date.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    };

    // Meditate: current streak of 5 (today and 4 days before)
    console.log('Creating Meditate completions (streak of 5)...');
    for (let i = 0; i < 5; i++) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      await pb.collection('completions').create({
        user_id: seedUser.id,
        habit_id: meditateHabit.id,
        date: formatDate(date)
      });
    }

    // Read 20 minutes: longest streak of 3, but not today
    console.log('Creating Read 20 minutes completions (longest streak 3, not today)...');
    for (let i = 7; i < 10; i++) {
      const date = new Date(today);
      date.setDate(date.getDate() - i);
      await pb.collection('completions').create({
        user_id: seedUser.id,
        habit_id: readHabit.id,
        date: formatDate(date)
      });
    }

    // No soda: current streak of 1 (only today)
    console.log('Creating No soda completion (today only)...');
    await pb.collection('completions').create({
      user_id: seedUser.id,
      habit_id: sodaHabit.id,
      date: formatDate(today)
    });

    console.log('Seed data setup complete!');

    // Write credentials to USER_README.md
    const fs = require('fs');
    const readme = `# Ethara - Habit Tracker

## Login Credentials

- **Email**: demo@ethara.ai
- **Password**: ${SEED_PASSWORD}

Use these credentials to sign in to the application.
`;

    fs.writeFileSync('/app/USER_README.md', readme);
    console.log('USER_README.md created');

  } catch (error) {
    console.error('Error setting up seed data:', error);
    if (error.response) {
      console.error('Response:', error.response);
    }
    throw error;
  }
}

// Run setup
setupSeedData()
  .then(() => {
    console.log('Done!');
    process.exit(0);
  })
  .catch((error) => {
    console.error('Failed:', error);
    process.exit(1);
  });

