const { chromium } = require('playwright');
const PocketBase = require('pocketbase').default;

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const ADMIN_EMAIL = 'admin@ethara.ai';
const ADMIN_PASSWORD = 'ethara-admin-2026-secure';
const SEED_PASSWORD = 'deku-demo-pw-2026';

async function setupPocketBaseUI() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  try {
    console.log('Navigating to PocketBase Admin UI...');
    await page.goto(`${BACKEND_URL}/_/`);
    await page.waitForTimeout(2000);

    // Check if we're on the setup page or login page
    const pageTitle = await page.title();
    console.log('Page title:', pageTitle);

    // Try to create admin if on setup page
    try {
      const emailInput = await page.waitForSelector('input[type="email"]', { timeout: 5000 });
      console.log('Found email input, attempting to create admin...');

      await emailInput.fill(ADMIN_EMAIL);
      const passwordInputs = await page.$$('input[type="password"]');

      if (passwordInputs.length >= 2) {
        await passwordInputs[0].fill(ADMIN_PASSWORD);
        await passwordInputs[1].fill(ADMIN_PASSWORD);

        const submitButton = await page.$('button[type="submit"]');
        if (submitButton) {
          await submitButton.click();
          await page.waitForTimeout(3000);
          console.log('Admin account created');
        }
      }
    } catch (error) {
      console.log('Not on setup page, trying login...');
      try {
        const emailInput = await page.$('input[type="email"]');
        if (emailInput) {
          await emailInput.fill(ADMIN_EMAIL);
          const passwordInput = await page.$('input[type="password"]');
          await passwordInput.fill(ADMIN_PASSWORD);

          const loginButton = await page.$('button[type="submit"]');
          await loginButton.click();
          await page.waitForTimeout(2000);
          console.log('Logged in as admin');
        }
      } catch (loginError) {
        console.log('Could not login:', loginError.message);
      }
    }

    await browser.close();

    // Now use the SDK with admin credentials
    await setupWithSDK();

  } catch (error) {
    console.error('Error in UI setup:', error);
    await browser.close();
    throw error;
  }
}

async function setupWithSDK() {
  const pb = new PocketBase(BACKEND_URL);

  try {
    // Authenticate as admin
    console.log('Authenticating as admin via SDK...');
    await pb.admins.authWithPassword(ADMIN_EMAIL, ADMIN_PASSWORD);
    console.log('Admin authenticated');

    // Check if collections exist
    let habitsCollection, completionsCollection;

    try {
      habitsCollection = await pb.collections.getOne('habits');
      console.log('Habits collection exists');
    } catch (err) {
      console.log('Creating habits collection...');
      habitsCollection = await pb.collections.create({
        name: 'habits',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: null
            }
          },
          {
            name: 'name',
            type: 'text',
            required: true,
            options: {
              min: 1,
              max: 80,
              pattern: ''
            }
          },
          {
            name: 'description',
            type: 'text',
            required: false,
            options: {
              min: null,
              max: 200,
              pattern: ''
            }
          },
          {
            name: 'color',
            type: 'select',
            required: true,
            options: {
              maxSelect: 1,
              values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest']
            }
          },
          {
            name: 'deleted',
            type: 'bool',
            required: false,
            options: {}
          }
        ],
        indexes: [],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = false',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != ""',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id',
      });
      console.log('Habits collection created');
    }

    try {
      completionsCollection = await pb.collections.getOne('completions');
      console.log('Completions collection exists');
    } catch (err) {
      console.log('Creating completions collection...');
      completionsCollection = await pb.collections.create({
        name: 'completions',
        type: 'base',
        schema: [
