const { chromium } = require('playwright');
const axios = require('axios');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const ADMIN_EMAIL = 'admin@ethara.ai';
const ADMIN_PASSWORD = 'admin123456789';
const SEED_PASSWORD = 'deku-demo-pw-2026';

async function setupAdmin() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Opening PocketBase Admin UI...');
    await page.goto(`${BACKEND_URL}/_/`, { waitUntil: 'networkidle' });
    await page.screenshot({ path: '/app/.browser_screenshots/pb-initial.png' });

    // Check the page content
    const hasEmail = await page.locator('input[type="email"]').count();
    console.log('Email inputs found:', hasEmail);

    if (hasEmail > 0) {
      console.log('Creating admin account...');
      await page.fill('input[type="email"]', ADMIN_EMAIL);

      const passwordInputs = await page.locator('input[type="password"]').all();
      console.log('Password inputs found:', passwordInputs.length);

      if (passwordInputs.length >= 2) {
        await passwordInputs[0].fill(ADMIN_PASSWORD);
        await passwordInputs[1].fill(ADMIN_PASSWORD);

        await page.screenshot({ path: '/app/.browser_screenshots/pb-filled.png' });

        // Click submit
        const submitBtn = await page.locator('button[type="submit"]').first();
        await submitBtn.click();

        await page.waitForTimeout(5000);
        await page.screenshot({ path: '/app/.browser_screenshots/pb-after-submit.png' });

        console.log('Admin account creation attempted');
      }
    }

    await browser.close();
  } catch (error) {
    await page.screenshot({ path: '/app/.browser_screenshots/pb-error.png' });
    await browser.close();
    console.error('Error in UI setup:', error.message);
  }
}

async function tryAuthenticateAdmin() {
  const passwords = [ADMIN_PASSWORD, 'admin', 'password', '12341234', SEED_PASSWORD];

  for (const password of passwords) {
    try {
      console.log(`Trying admin auth with password: ${password.substring(0, 3)}...`);
      const response = await axios.post(`${BACKEND_URL}/api/admins/auth-with-password`, {
        identity: ADMIN_EMAIL,
        password: password
      });

      if (response.data.token) {
        console.log('✓ Admin authenticated successfully');
        return response.data.token;
      }
    } catch (error) {
      // Try next password
    }
  }

  throw new Error('Could not authenticate as admin with any known password');
}

async function setupCollectionsAndData(adminToken) {
  const headers = {
    'Content-Type': 'application/json',
    'Authorization': adminToken
  };

  // Create habits collection
  console.log('Creating habits collection...');
  try {
    await axios.post(`${BACKEND_URL}/api/collections`, {
      name: 'habits',
      type: 'base',
      schema: [
        { name: 'user_id', type: 'relation', required: true, options: { collectionId: '_pb_users_auth_', cascadeDelete: false, minSelect: null, maxSelect: 1, displayFields: null } },
        { name: 'name', type: 'text', required: true, options: { min: 1, max: 80, pattern: '' } },
        { name: 'description', type: 'text', required: false, options: { min: null, max: 200, pattern: '' } },
        { name: 'color', type: 'select', required: true, options: { maxSelect: 1, values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest'] } },
        { name: 'deleted', type: 'bool', required: false, options: {} }
      ],
      listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = false',
      viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
      createRule: '@request.auth.id != ""',
      updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
      deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
    }, { headers });
    console.log('✓ Habits collection created');
  } catch (error) {
    console.log('Habits collection may already exist');
  }

  // Get collections to find habits ID
  const collections = await axios.get(`${BACKEND_URL}/api/collections`, { headers });
  const habitsCollection = collections.data.find(c => c.name === 'habits');

  // Create completions collection
  console.log('Creating completions collection...');
  try {
    await axios.post(`${BACKEND_URL}/api/collections`, {
      name: 'completions',
      type: 'base',
      schema: [
        { name: 'user_id', type: 'relation', required: true, options: { collectionId: '_pb_users_auth_', cascadeDelete: false, minSelect: null, maxSelect: 1, displayFields: null } },
        { name: 'habit_id', type: 'relation', required: true, options: { collectionId: habitsCollection.id, cascadeDelete: true, minSelect: null, maxSelect: 1, displayFields: null } },
        { name: 'date', type: 'text', required: true, options: { min: 10, max: 10, pattern: '^\\d{4}-\\d{2}-\\d{2}$' } }
      ],
      listRule: '@request.auth.id != "" && user_id = @request.auth.id',
      viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
      createRule: '@request.auth.id != ""',
      deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
    }, { headers });
    console.log('✓ Completions collection created');
  } catch (error) {
    console.log('Completions collection may already exist');
  }

  // Create and auth as seed user
  console.log('Setting up seed user...');
  let userToken;
  try {
    await axios.post(`${BACKEND_URL}/api/collections/users/records`, {
      email: 'demo@ethara.ai',
      password: SEED_PASSWORD,
      passwordConfirm: SEED_PASSWORD
    });
    console.log('Seed user created');
  } catch (error) {
    console.log('Seed user may already exist');
  }

  const authResp = await axios.post(`${BACKEND_URL}/api/collections/users/auth-with-password`, {
    identity: 'demo@ethara.ai',
    password: SEED_PASSWORD
  });
  userToken = authResp.data.token;
  const seedUser = authResp.data.record;
  console.log('✓ Authenticated as seed user');

  const userHeaders = { 'Content-Type': 'application/json', 'Authorization': userToken };

  // Check if seed data exists
  try {
    const existing = await axios.get(`${BACKEND_URL}/api/collections/habits/records`, { headers: userHeaders });
    if (existing.data.items && existing.data.items.length > 0) {
      console.log('✓ Seed data already exists');
      return;
    }
  } catch (error) {
    // Continue
  }

  console.log('Creating seed habits...');
  const meditate = await axios.post(`${BACKEND_URL}/api/collections/habits/records`, {
    user_id: seedUser.id, name: 'Meditate', color: 'indigo', description: '', deleted: false
  }, { headers: userHeaders });

  const read = await axios.post(`${BACKEND_URL}/api/collections/habits/records`, {
    user_id: seedUser.id, name: 'Read 20 minutes', color: 'teal', description: '', deleted: false
  }, { headers: userHeaders });

  const soda = await axios.post(`${BACKEND_URL}/api/collections/habits/records`, {
    user_id: seedUser.id, name: 'No soda', color: 'amber', description: '', deleted: false
  }, { headers: userHeaders });

  console.log('✓ Seed habits created');

  console.log('Creating seed completions...');
  const today = new Date();
  const fmt = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;

  // Meditate: 5-day streak
