      user_id: seedUser.id, habit_id: meditate.data.id, date: fmt(d)
    }, { headers: userHeaders });
  }

  // Read: 3-day streak (7-9 days ago)
  for (let i = 7; i < 10; i++) {
    const d = new Date(today); d.setDate(d.getDate() - i);
    await axios.post(`${BACKEND_URL}/api/collections/completions/records`, {
      user_id: seedUser.id, habit_id: read.data.id, date: fmt(d)
    }, { headers: userHeaders });
