const axios = require('axios');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const SEED_PASSWORD = 'deku-demo-pw-2026';

async function createSeedData() {
  try {
    console.log('Creating seed user...');
    let seedUser;
    try {
      await axios.post(`${BACKEND_URL}/api/collections/users/records`, {
        email: 'demo@ethara.ai',
        password: SEED_PASSWORD,
        passwordConfirm: SEED_PASSWORD
      });
      console.log('✓ Seed user created');
    } catch (error) {
      console.log('Seed user may already exist');
    }

    // Authenticate as seed user
    const authResp = await axios.post(`${BACKEND_URL}/api/collections/users/auth-with-password`, {
      identity: 'demo@ethara.ai',
      password: SEED_PASSWORD
    });
    const userToken = authResp.data.token;
    const seedUser = authResp.data.record;
    console.log('✓ Authenticated as seed user');

    const headers = { 'Content-Type': 'application/json', 'Authorization': userToken };

    // Check if seed data already exists
    try {
      const existing = await axios.get(`${BACKEND_URL}/api/collections/habits/records`, { headers });
      if (existing.data.items && existing.data.items.length > 0) {
        console.log('✓ Seed habits already exist');
        console.log('Existing habits:', existing.data.items.map(h => h.name).join(', '));
        return;
      }
    } catch (error) {
      console.log('Checking existing habits...');
    }

    console.log('Creating seed habits...');
    const meditate = await axios.post(`${BACKEND_URL}/api/collections/habits/records`, {
      user_id: seedUser.id,
      name: 'Meditate',
      color: 'indigo',
      description: '',
      deleted: false
    }, { headers });
    console.log('✓ Created: Meditate');

    const read = await axios.post(`${BACKEND_URL}/api/collections/habits/records`, {
      user_id: seedUser.id,
      name: 'Read 20 minutes',
      color: 'teal',
      description: '',
      deleted: false
    }, { headers });
    console.log('✓ Created: Read 20 minutes');

    const soda = await axios.post(`${BACKEND_URL}/api/collections/habits/records`, {
      user_id: seedUser.id,
      name: 'No soda',
      color: 'amber',
      description: '',
      deleted: false
    }, { headers });
    console.log('✓ Created: No soda');

    console.log('Creating seed completions...');
    const today = new Date();
    const fmt = d => {
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${y}-${m}-${day}`;
    };

    // Meditate: 5-day streak (today and 4 days before)
    for (let i = 0; i < 5; i++) {
      const d = new Date(today);
      d.setDate(d.getDate() - i);
      await axios.post(`${BACKEND_URL}/api/collections/completions/records`, {
        user_id: seedUser.id,
        habit_id: meditate.data.id,
        date: fmt(d)
      }, { headers });
    }
    console.log('✓ Created Meditate completions (5-day streak)');

    // Read: 3-day streak (7-9 days ago, not today)
    for (let i = 7; i < 10; i++) {
      const d = new Date(today);
      d.setDate(d.getDate() - i);
      await axios.post(`${BACKEND_URL}/api/collections/completions/records`, {
        user_id: seedUser.id,
        habit_id: read.data.id,
        date: fmt(d)
      }, { headers });
    }
    console.log('✓ Created Read 20 minutes completions (longest streak 3, not today)');

    // No soda: today only (streak of 1)
    await axios.post(`${BACKEND_URL}/api/collections/completions/records`, {
      user_id: seedUser.id,
      habit_id: soda.data.id,
      date: fmt(today)
    }, { headers });
    console.log('✓ Created No soda completion (today only)');

    // Write USER_README.md
    require('fs').writeFileSync('/app/USER_README.md',
      `# Ethara - Habit Tracker\n\n## Login Credentials\n\n- **Email**: demo@ethara.ai\n- **Password**: ${SEED_PASSWORD}\n\nUse these credentials to sign in to the application.\n`
    );
    console.log('✓ USER_README.md created');

    console.log('\n✓✓✓ Seed data setup complete! ✓✓✓\n');
  } catch (error) {
    console.error('\n✗ Setup failed:', error.message);
    if (error.response) {
      console.error('Response:', error.response.data);
    }
    process.exit(1);
  }
}

