const { chromium } = require('playwright');

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';

async function fixPermissions() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  try {
    console.log('Opening PocketBase Admin UI...');
    await page.goto(`${BACKEND_URL}/_/`, { waitUntil: 'networkidle', timeout: 30000 });

    // Take initial screenshot
    await page.screenshot({ path: '/app/.browser_screenshots/admin-login.png' });

    // Try to find and fill login form
    const emailInput = await page.locator('input[type="email"]').first();
    const passwordInput = await page.locator('input[type="password"]').first();

    if (emailInput && passwordInput) {
      // Try common credentials
      const credentials = [
        { email: 'admin@ethara.ai', password: 'admin123456789' },
        { email: 'admin@example.com', password: 'admin1234' },
        { email: 'admin@admin.com', password: 'password' }
      ];

      for (const cred of credentials) {
        console.log(`Trying to login with ${cred.email}...`);
        await emailInput.fill(cred.email);
        await passwordInput.fill(cred.password);

        const submitBtn = await page.locator('button[type="submit"]').first();
        await submitBtn.click();

        await page.waitForTimeout(3000);
        const currentUrl = page.url();

        if (!currentUrl.includes('/_/login')) {
          console.log('✓ Logged in successfully!');
          await page.screenshot({ path: '/app/.browser_screenshots/admin-dashboard.png' });

          // Navigate to collections
          await page.goto(`${BACKEND_URL}/_/#/collections`, { waitUntil: 'networkidle' });
          await page.waitForTimeout(2000);
          await page.screenshot({ path: '/app/.browser_screenshots/collections-list.png' });

          console.log('Access the screenshots to see the current state');
          console.log('Admin credentials that worked:', cred.email, cred.password);

          await browser.close();
          return true;
        }

        // Reset for next attempt
        await page.goto(`${BACKEND_URL}/_/`, { waitUntil: 'networkidle' });
      }
    }

    console.log('Could not login with any credentials');
    await browser.close();
    return false;

  } catch (error) {
    console.error('Error:', error.message);
    await page.screenshot({ path: '/app/.browser_screenshots/error.png' });
    await browser.close();
    return false;
  }
}

fixPermissions().then(success => {
  if (!success) {
    console.log('\nCould not access admin UI.');
    console.log('Please check screenshots in /app/.browser_screenshots/');
  }
  process.exit(success ? 0 : 1);
});

