import type {
  AuthResponse,
  Habit,
  Dashboard,
  CreateHabitRequest,
  UpdateHabitRequest,
  CompleteHabitRequest,
} from '../types';

class ApiClient {
  private baseUrl = '/api';
  private token: string | null = null;

  setToken(token: string | null) {
    this.token = token;
    if (token) {
      localStorage.setItem('auth_token', token);
    } else {
      localStorage.removeItem('auth_token');
    }
  }

  getToken(): string | null {
    if (!this.token) {
      this.token = localStorage.getItem('auth_token');
    }
    return this.token;
  }

  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const token = this.getToken();
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      ...options.headers,
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const response = await fetch(`${this.baseUrl}${endpoint}`, {
      ...options,
      headers,
    });

    if (response.status === 401) {
      this.setToken(null);
      window.location.href = '/login?next=' + encodeURIComponent(window.location.pathname);
      throw new Error('Unauthorized');
    }

    if (!response.ok) {
      const error = await response.json().catch(() => ({ message: 'Request failed' }));
      throw new Error(error.message || `Request failed with status ${response.status}`);
    }

    if (response.status === 204) {
      return {} as T;
    }

    return response.json();
  }

  // Auth
  async login(email: string, password: string): Promise<AuthResponse> {
    const response = await this.request<AuthResponse>('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ email, password }),
    });
    this.setToken(response.access_token);
    return response;
  }

  logout() {
    this.setToken(null);
  }

  // Habits
  async getHabits(): Promise<Habit[]> {
    return this.request<Habit[]>('/habits');
  }

  async getHabit(id: string): Promise<Habit> {
    return this.request<Habit>(`/habits/${id}`);
  }

  async createHabit(data: CreateHabitRequest): Promise<Habit> {
    return this.request<Habit>('/habits', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async updateHabit(id: string, data: UpdateHabitRequest): Promise<Habit> {
    return this.request<Habit>(`/habits/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(data),
    });
  }

  async deleteHabit(id: string): Promise<void> {
    return this.request<void>(`/habits/${id}`, {
      method: 'DELETE',
    });
  }

  async completeHabit(id: string, data: CompleteHabitRequest): Promise<void> {
    return this.request<void>(`/habits/${id}/complete`, {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }

  async uncompleteHabit(id: string, data: CompleteHabitRequest): Promise<void> {
    return this.request<void>(`/habits/${id}/complete`, {
      method: 'DELETE',
      body: JSON.stringify(data),
    });
  }

  // Dashboard
  async getDashboard(): Promise<Dashboard> {
    return this.request<Dashboard>('/dashboard');
  }

  // Health
  async health(): Promise<void> {
    return this.request<void>('/health');
  }
}

export const api = new ApiClient();

import { ReactNode } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../lib/auth-context';

interface LayoutProps {
  children: ReactNode;
}

export function Layout({ children }: LayoutProps) {
  const { user, logout, isAuthenticated } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  if (!isAuthenticated) {
    return <>{children}</>;
  }

  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-surface border-b border-border">
        <div className="max-w-7xl mx-auto px-4">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-8">
              <Link to="/" className="text-heading-4 font-semibold text-text-primary">
                Ethara
              </Link>
              <div className="hidden md:flex gap-6">
                <Link
                  to="/"
                  className="text-body text-text-muted hover:text-text-primary transition-colors"
                >
                  Dashboard
                </Link>
                <Link
                  to="/habits"
                  className="text-body text-text-muted hover:text-text-primary transition-colors"
                >
                  Habits
                </Link>
              </div>
            </div>

            <div className="flex items-center gap-4">
              {user && (
                <span className="text-body text-text-muted hidden sm:inline">{user.email}</span>
              )}
              <button
                onClick={handleLogout}
                className="text-body text-text-muted hover:text-text-primary transition-colors"
              >
                Sign out
              </button>
            </div>
          </div>

          {/* Mobile menu */}
          <div className="md:hidden pb-4 flex gap-6">
            <Link
              to="/"
              className="text-body text-text-muted hover:text-text-primary transition-colors"
            >
              Dashboard
            </Link>
            <Link
              to="/habits"
              className="text-body text-text-muted hover:text-text-primary transition-colors"
            >
              Habits
            </Link>
          </div>
        </div>
      </nav>

      <main className="flex-1">{children}</main>
    </div>
  );
}

import { ReactNode } from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAuth } from '../lib/auth-context';

interface ProtectedRouteProps {
  children: ReactNode;
}

export function ProtectedRoute({ children }: ProtectedRouteProps) {
  const { isAuthenticated } = useAuth();
  const location = useLocation();

  if (!isAuthenticated) {
    return <Navigate to={`/login?next=${encodeURIComponent(location.pathname)}`} replace />;
  }

  return <>{children}</>;
}

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { api } from './api';
import type { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);

  useEffect(() => {
    const token = api.getToken();
    if (token) {
      setIsAuthenticated(true);
    }
  }, []);

  const login = async (email: string, password: string) => {
    const response = await api.login(email, password);
    setUser(response.record);
    setIsAuthenticated(true);
  };

  const logout = () => {
    api.logout();
    setUser(null);
    setIsAuthenticated(false);
  };

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

