// Create habit
app.post('/api/habits', authMiddleware, async (req, res) => {
  try {
    const { name, color, description } = req.body;

    if (!name || !color) {
      return res.status(400).json({ message: 'Name and color are required' });
    }

    // Check for duplicate name (case-insensitive)
    const existing = await pb.collection('habits').getFullList({
      filter: `user_id = "${req.user.id}" && LOWER(name) = LOWER("${name.replace(/"/g, '\\"')}") && deleted = false`
    });

    if (existing.length > 0) {
      return res.status(400).json({ message: 'A habit with this name already exists' });
    }

    const habit = await pb.collection('habits').create({
      user_id: req.user.id,
      name: name.trim(),
      color,
      description: description?.trim() || '',
      deleted: false
    });

    res.status(201).json({
      ...habit,
      current_streak: 0,
      longest_streak: 0,
      completed_today: false
    });
  } catch (error) {
    console.error('Create habit error:', error);
    res.status(400).json({ message: error.message || 'Failed to create habit' });

